316	        boolean inUse = this.clinicService.findAllOwners().stream()
317	            .map(Owner::getTelephone)
318	            .map(this::digitsOnly)
319	            .anyMatch(telephone::equals);
320	        if (inUse) {
321	            throw new DuplicateOwnerTelephoneException(telephone);
322	        }
323	    }
